        /// <summary>
        /// Serializes a tree in pre-order with thresholds and leaf values as IEEE-754 bit patterns.
        /// </summary>
        /// <param name="node">The root of the subtree to serialize.</param>
        /// <returns>One pipe-delimited entry per node.</returns>
        private static string SerializeTree(DecisionNode node)
        {
            var sb = new StringBuilder();
            void Walk(DecisionNode n)
            {
                if (n == null) return;
                sb.Append(n.FeatureIndex).Append(';')
                  .Append(BitConverter.DoubleToInt64Bits(n.Threshold).ToString("X16")).Append(';')
                  .Append(BitConverter.DoubleToInt64Bits(n.Value).ToString("X16")).Append(';')
                  .Append(n.IsLeafNode ? '1' : '0').Append('|');
                Walk(n.Left); Walk(n.Right);
            }
            Walk(node);
            return sb.ToString();
        }

        /// <summary>
        /// Serializes the leading columns of a prediction matrix as IEEE-754 bit patterns.
        /// </summary>
        /// <param name="p">The prediction matrix.</param>
        /// <param name="cols">The number of leading columns to serialize.</param>
        /// <returns>One pipe-delimited entry per cell, row major.</returns>
        private static string SerializeColumns(double[,] p, int cols)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < p.GetLength(0); i++)
                for (int j = 0; j < cols; j++)
                    sb.Append(BitConverter.DoubleToInt64Bits(p[i, j]).ToString("X16")).Append('|');
            return sb.ToString();
        }

        private static Matrix IrisTrainX() => new Matrix(new List<double[]> { sepalLengthTrain, sepalWidthTrain, petalLengthTrain, petalWidthTrain });
        private static Vector IrisTrainY() => new Vector(speciesTrain);
        private static Matrix IrisTestX() => new Matrix(new List<double[]> { sepalLengthTest, sepalWidthTest, petalLengthTest, petalWidthTest });

        /// <summary>
        /// Returns the subarray from <paramref name="start"/> through <paramref name="endInclusive"/>,
        /// or through the final element when <paramref name="endInclusive"/> is negative.
        /// </summary>
        /// <param name="a">The source array.</param>
        /// <param name="start">The first index to copy.</param>
        /// <param name="endInclusive">The last index to copy, or a negative value for the end of the array.</param>
        private static double[] Sub(double[] a, int start, int endInclusive)
        {
            int len = (endInclusive < 0 ? a.Length : endInclusive + 1) - start;
            var r = new double[len];
            Array.Copy(a, start, r, 0, len);
            return r;
        }

        private static Matrix RegressionTrainX() => new Matrix(new List<double[]> { Sub(income, 0, 118), Sub(production, 0, 118), Sub(savings, 0, 118), Sub(unemployment, 0, 118) });
        private static Vector RegressionTrainY() => new Vector(Sub(consumption, 0, 118));
        private static Matrix RegressionTestX() => new Matrix(new List<double[]> { Sub(income, 119, -1), Sub(production, 119, -1), Sub(savings, 119, -1), Sub(unemployment, 119, -1) });

        /// <summary>
        /// The Iris classification tree grown from seed 12345 with all four features must reproduce
        /// the pinned structure node for node at full precision.
        /// </summary>
        [TestMethod]
        public void Test_DecisionTree_GoldenStructure_Iris()
        {
            var dt = new DecisionTree(IrisTrainX(), IrisTrainY(), 12345) { IsRegression = false, Features = 4 };
            dt.Train();
            Assert.AreEqual(GoldenDecisionTreeIris, SerializeTree(dt.Root));
        }

        /// <summary>
        /// The consumption regression tree grown from seed 12345 with all four features must
        /// reproduce the pinned structure node for node at full precision.
        /// </summary>
        [TestMethod]
        public void Test_DecisionTree_GoldenStructure_Regression()
        {
            var dt = new DecisionTree(RegressionTrainX(), RegressionTrainY(), 12345) { Features = 4 };
            dt.Train();
            Assert.AreEqual(GoldenDecisionTreeRegression, SerializeTree(dt.Root));
        }

        /// <summary>
        /// The Iris random forest from seed 12345 must reproduce every pinned prediction cell
        /// bit for bit on the held-out rows, mean column included.
        /// </summary>
        [TestMethod]
        public void Test_RandomForest_GoldenPredictions_Iris()
        {
            var rf = new RandomForest(IrisTrainX(), IrisTrainY(), 12345) { IsRegression = false, Features = 4 };
            rf.Train();
            Assert.AreEqual(GoldenForestIrisPredictions, SerializeColumns(rf.Predict(IrisTestX())!, 4));
        }

        /// <summary>
        /// The consumption regression random forest from seed 12345 must reproduce every pinned
        /// prediction cell bit for bit on the held-out rows, mean column included.
        /// </summary>
        [TestMethod]
        public void Test_RandomForest_GoldenPredictions_Regression()
        {
            var rf = new RandomForest(RegressionTrainX(), RegressionTrainY(), 12345) { Features = 4 };
            rf.Train();
            Assert.AreEqual(GoldenForestRegressionPredictions, SerializeColumns(rf.Predict(RegressionTestX())!, 4));
        }

        /// <summary>
        /// Repeated predictions from one trained forest must be bit-for-bit identical across all
        /// four output columns, including the mean.
        /// </summary>
        [TestMethod]
        public void Test_RandomForest_PredictIsDeterministic()
        {
            var rf = new RandomForest(RegressionTrainX(), RegressionTrainY(), 12345) { Features = 4 };
            rf.Train();
            var first = rf.Predict(RegressionTestX())!;
            var second = rf.Predict(RegressionTestX())!;
            for (int i = 0; i < first.GetLength(0); i++)
                for (int j = 0; j < 4; j++)
                    Assert.AreEqual(BitConverter.DoubleToInt64Bits(first[i, j]), BitConverter.DoubleToInt64Bits(second[i, j]), $"cell [{i},{j}]");
        }

        /// <summary>
        /// The root split of the regression tree must match the best split determined by exhaustive
        /// search in exact rational arithmetic over every candidate threshold of every feature.
        /// </summary>
        [TestMethod]
        public void Test_DecisionTree_BestSplitMatchesExactOracle()
        {
            var x = new Matrix(new List<double[]> { OracleX0, OracleX1, OracleX2 });
            var y = new Vector(OracleY);
            var dt = new DecisionTree(x, y, 12345) { Features = 3 };
            dt.Train();
            Assert.AreEqual(OracleBestFeature, dt.Root.FeatureIndex);
            Assert.AreEqual(BitConverter.DoubleToInt64Bits(OracleBestThreshold), BitConverter.DoubleToInt64Bits(dt.Root.Threshold));
        }
    }
